    $required = @('InstallRoot','ParentPid','PurgeSettings','MsiProductCode','SharedProgress')
    if ($parseErrors.Count -or @($required | Where-Object { $_ -notin $parameters }).Count) {
        throw 'CC-UNINSTALL-COMPAT-004: the paired finalizer does not support the shared progress protocol; removal was not started.'
    }
}
